import React, { useState, useEffect } from 'react';
import {
  Card,
  Row,
  Col,
  Statistic,
  Table,
  Button,
  Progress,
  Tag,
  Space,
  Modal,
  Form,
  InputNumber,
  Select,
  Input,
  message,
  Tabs,
  Alert,
  Spin,
  Tooltip
} from 'antd';
import {
  SyncOutlined,
  AimOutlined,
  TrophyOutlined,
  RocketOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  ExclamationCircleOutlined,
  ReloadOutlined,
  PlayCircleOutlined,
  BarChartOutlined
} from '@ant-design/icons';

const { TabPane } = Tabs;
const { TextArea } = Input;

interface ActivityGoal {
  id: string;
  title: string;
  priority: number;
  quantum_goals_count: number;
  completed_goals: number;
  average_progress: number;
  completion_rate: number;
}

interface DashboardData {
  overview: {
    total_activities: number;
    total_activity_goals: number;
    total_quantum_goals: number;
    completed_quantum_goals: number;
    total_milestones: number;
    completed_milestones: number;
    average_milestone_progress: number;
    integration_coverage: number;
    goals_completion_rate: number;
    milestones_completion_rate: number;
  };
  top_activities: ActivityGoal[];
}

interface ActivitySummary {
  activity_id: string;
  activity_title: string;
  activity_priority: number;
  total_activity_goals: number;
  total_quantum_goals: number;
  completed_goals: number;
  total_milestones: number;
  completed_milestones: number;
  average_progress: number;
  goals_completion_rate: number;
  milestones_completion_rate: number;
}

const ActivityGoalsIntegration: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [selectedActivity, setSelectedActivity] = useState<string | null>(null);
  const [activitySummary, setActivitySummary] = useState<ActivitySummary | null>(null);
  const [progressModalVisible, setProgressModalVisible] = useState(false);
  const [syncModalVisible, setSyncModalVisible] = useState(false);
  const [form] = Form.useForm();

  useEffect(() => {
    loadDashboard();
  }, []);

  const loadDashboard = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/activities/goals/dashboard');
      const result = await response.json();
      
      if (result.status === 'success') {
        setDashboardData(result.data);
      } else {
        message.error('Ошибка загрузки дашборда');
      }
    } catch (error) {
      console.error('Error loading dashboard:', error);
      message.error('Ошибка подключения к серверу');
    } finally {
      setLoading(false);
    }
  };

  const syncAllActivities = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/activities/goals/sync-all', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      const result = await response.json();
      
      if (result.status === 'success') {
        message.success(`Синхронизировано активностей: ${result.details.synced_activities}`);
        loadDashboard();
      } else {
        message.error('Ошибка синхронизации');
      }
    } catch (error) {
      console.error('Error syncing activities:', error);
      message.error('Ошибка синхронизации');
    } finally {
      setLoading(false);
    }
  };

  const syncActivity = async (activityId: string) => {
    setLoading(true);
    try {
      const response = await fetch(`/api/activities/goals/sync/${activityId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      const result = await response.json();
      
      if (result.status === 'success') {
        message.success('Активность синхронизирована');
        loadDashboard();
        if (selectedActivity === activityId) {
          loadActivitySummary(activityId);
        }
      } else {
        message.error('Ошибка синхронизации активности');
      }
    } catch (error) {
      console.error('Error syncing activity:', error);
      message.error('Ошибка синхронизации активности');
    } finally {
      setLoading(false);
    }
  };

  const loadActivitySummary = async (activityId: string) => {
    try {
      const response = await fetch(`/api/activities/goals/summary/${activityId}`);
      const result = await response.json();
      
      if (result.status === 'success') {
        setActivitySummary(result.data);
      } else {
        message.error('Ошибка загрузки сводки активности');
      }
    } catch (error) {
      console.error('Error loading activity summary:', error);
      message.error('Ошибка загрузки сводки активности');
    }
  };

  const updateProgress = async (values: any) => {
    if (!selectedActivity) return;
    
    setLoading(true);
    try {
      const response = await fetch(`/api/activities/goals/progress/${selectedActivity}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(values)
      });
      const result = await response.json();
      
      if (result.status === 'success') {
        message.success('Прогресс обновлен');
        setProgressModalVisible(false);
        form.resetFields();
        loadDashboard();
        loadActivitySummary(selectedActivity);
      } else {
        message.error('Ошибка обновления прогресса');
      }
    } catch (error) {
      console.error('Error updating progress:', error);
      message.error('Ошибка обновления прогресса');
    } finally {
      setLoading(false);
    }
  };

  const testIntegration = async () => {
    setLoading(true);
    try {
      const testData = {
        create_test_activity: true,
        title: "Тестовая активность интеграции",
        description: "Проверка работы интеграции целей и активностей",
        priority: 0.8,
        goals: [
          { goal_type: "regular", priority: 0.9, description: "Тестовая обычная цель" },
          { goal_type: "absolute", priority: 0.7, description: "Тестовая критическая цель" }
        ]
      };

      const response = await fetch('/api/activities/goals/test-integration', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(testData)
      });
      const result = await response.json();
      
      if (result.status === 'success') {
        message.success(`Тест завершен! ID активности: ${result.test_activity_id}`);
        loadDashboard();
      } else {
        message.error('Ошибка тестирования');
      }
    } catch (error) {
      console.error('Error testing integration:', error);
      message.error('Ошибка тестирования');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (rate: number) => {
    if (rate >= 80) return '#52c41a';
    if (rate >= 50) return '#faad14';
    return '#f5222d';
  };

  const getStatusTag = (rate: number) => {
    if (rate >= 80) return <Tag color="success">Отлично</Tag>;
    if (rate >= 50) return <Tag color="warning">Хорошо</Tag>;
    return <Tag color="error">Требует внимания</Tag>;
  };

  const activityColumns = [
    {
      title: 'Активность',
      dataIndex: 'title',
      key: 'title',
      render: (text: string, record: ActivityGoal) => (
        <Space direction="vertical" size="small">
          <strong>{text}</strong>
          <Tag color="blue">Приоритет: {record.priority.toFixed(2)}</Tag>
        </Space>
      ),
    },
    {
      title: 'Квантовые цели',
      dataIndex: 'quantum_goals_count',
      key: 'quantum_goals_count',
      render: (count: number, record: ActivityGoal) => (
        <Space direction="vertical" size="small">
          <Statistic 
            value={count} 
            suffix={`/ ${record.completed_goals} завершено`}
            valueStyle={{ fontSize: '14px' }}
          />
          <Progress 
            percent={record.completion_rate} 
            size="small" 
            strokeColor={getStatusColor(record.completion_rate)}
          />
        </Space>
      ),
    },
    {
      title: 'Средний прогресс',
      dataIndex: 'average_progress',
      key: 'average_progress',
      render: (progress: number) => (
        <Progress 
          percent={progress} 
          strokeColor={getStatusColor(progress)}
          format={(percent) => `${percent?.toFixed(1)}%`}
        />
      ),
    },
    {
      title: 'Статус',
      key: 'status',
      render: (record: ActivityGoal) => getStatusTag(record.completion_rate),
    },
    {
      title: 'Действия',
      key: 'actions',
      render: (record: ActivityGoal) => (
        <Space>
          <Button 
            size="small" 
            icon={<BarChartOutlined />}
            onClick={() => {
              setSelectedActivity(record.id);
              loadActivitySummary(record.id);
            }}
          >
            Детали
          </Button>
          <Button 
            size="small" 
            icon={<SyncOutlined />}
            onClick={() => syncActivity(record.id)}
          >
            Синхронизировать
          </Button>
          <Button 
            size="small" 
            icon={<PlayCircleOutlined />}
            onClick={() => {
              setSelectedActivity(record.id);
              setProgressModalVisible(true);
            }}
          >
            Прогресс
          </Button>
        </Space>
      ),
    },
  ];

  if (loading && !dashboardData) {
    return (
      <div style={{ textAlign: 'center', padding: '50px' }}>
        <Spin size="large" />
        <p>Загрузка дашборда интеграции...</p>
      </div>
    );
  }

  return (
    <div style={{ padding: '24px' }}>
      <div style={{ marginBottom: '24px' }}>
        <h1>
          <RocketOutlined style={{ marginRight: '8px', color: '#1890ff' }} />
          Интеграция Активностей и Целей
        </h1>
        <p>Управление связями между активностями и квантовыми целями системы</p>
      </div>

      <Row gutter={[16, 16]} style={{ marginBottom: '24px' }}>
        <Col span={6}>
          <Card>
            <Statistic
              title="Всего активностей"
              value={dashboardData?.overview.total_activities || 0}
              prefix={<AimOutlined />}
              valueStyle={{ color: '#1890ff' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Квантовые цели"
              value={dashboardData?.overview.total_quantum_goals || 0}
              suffix={`/ ${dashboardData?.overview.total_activity_goals || 0}`}
              prefix={<TrophyOutlined />}
              valueStyle={{ color: '#52c41a' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Завершено целей"
              value={dashboardData?.overview.completed_quantum_goals || 0}
              prefix={<CheckCircleOutlined />}
              valueStyle={{ color: '#722ed1' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="Покрытие интеграции"
              value={dashboardData?.overview.integration_coverage || 0}
              suffix="%"
              prefix={<SyncOutlined />}
              valueStyle={{ color: '#fa8c16' }}
            />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} style={{ marginBottom: '24px' }}>
        <Col span={8}>
          <Card title="Прогресс целей" size="small">
            <Progress 
              type="circle" 
              percent={dashboardData?.overview.goals_completion_rate || 0}
              strokeColor={getStatusColor(dashboardData?.overview.goals_completion_rate || 0)}
              format={(percent) => `${percent?.toFixed(1)}%`}
            />
            <p style={{ textAlign: 'center', marginTop: '8px' }}>
              Завершение целей
            </p>
          </Card>
        </Col>
        <Col span={8}>
          <Card title="Прогресс этапов" size="small">
            <Progress 
              type="circle" 
              percent={dashboardData?.overview.milestones_completion_rate || 0}
              strokeColor={getStatusColor(dashboardData?.overview.milestones_completion_rate || 0)}
              format={(percent) => `${percent?.toFixed(1)}%`}
            />
            <p style={{ textAlign: 'center', marginTop: '8px' }}>
              Завершение этапов
            </p>
          </Card>
        </Col>
        <Col span={8}>
          <Card title="Средний прогресс" size="small">
            <Progress 
              type="circle" 
              percent={dashboardData?.overview.average_milestone_progress || 0}
              strokeColor={getStatusColor(dashboardData?.overview.average_milestone_progress || 0)}
              format={(percent) => `${percent?.toFixed(1)}%`}
            />
            <p style={{ textAlign: 'center', marginTop: '8px' }}>
              По всем этапам
            </p>
          </Card>
        </Col>
      </Row>

      <Card 
        title="Управление интеграцией" 
        style={{ marginBottom: '24px' }}
        extra={
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'flex-end', maxWidth: '100%' }}>
            <Button size="small" type="primary" icon={<SyncOutlined />} onClick={syncAllActivities} loading={loading}>
              Синхронизировать все
            </Button>
            <Button size="small" icon={<PlayCircleOutlined />} onClick={testIntegration} loading={loading}>
              Тест интеграции
            </Button>
            <Button size="small" icon={<ReloadOutlined />} onClick={loadDashboard} loading={loading}>
              Обновить
            </Button>
          </div>
        }
      >
        <Alert
          message="Система интеграции активностей и целей"
          description="Автоматически синхронизирует activity_goals с quantum_goals, отслеживает прогресс выполнения и управляет этапами достижения целей."
          type="info"
          showIcon
          style={{ marginBottom: '16px' }}
        />
      </Card>

      <Tabs defaultActiveKey="activities">
        <TabPane tab="Активности" key="activities">
          <Table
            columns={activityColumns}
            dataSource={dashboardData?.top_activities || []}
            rowKey="id"
            loading={loading}
            pagination={{ pageSize: 10 }}
          />
        </TabPane>
        
        <TabPane tab="Детали активности" key="details" disabled={!selectedActivity}>
          {activitySummary && (
            <Card title={`Активность: ${activitySummary.activity_title}`}>
              <Row gutter={[16, 16]}>
                <Col span={8}>
                  <Statistic
                    title="Цели активности"
                    value={activitySummary.total_activity_goals}
                    prefix={<AimOutlined />}
                  />
                </Col>
                <Col span={8}>
                  <Statistic
                    title="Квантовые цели"
                    value={activitySummary.total_quantum_goals}
                    prefix={<TrophyOutlined />}
                  />
                </Col>
                <Col span={8}>
                  <Statistic
                    title="Завершено целей"
                    value={activitySummary.completed_goals}
                    prefix={<CheckCircleOutlined />}
                  />
                </Col>
              </Row>
              
              <Row gutter={[16, 16]} style={{ marginTop: '16px' }}>
                <Col span={12}>
                  <Card title="Прогресс целей" size="small">
                    <Progress 
                      percent={activitySummary.goals_completion_rate}
                      strokeColor={getStatusColor(activitySummary.goals_completion_rate)}
                    />
                  </Card>
                </Col>
                <Col span={12}>
                  <Card title="Прогресс этапов" size="small">
                    <Progress 
                      percent={activitySummary.milestones_completion_rate}
                      strokeColor={getStatusColor(activitySummary.milestones_completion_rate)}
                    />
                  </Card>
                </Col>
              </Row>
            </Card>
          )}
        </TabPane>
      </Tabs>

      <Modal
        title="Обновить прогресс активности"
        open={progressModalVisible}
        onCancel={() => setProgressModalVisible(false)}
        onOk={() => form.submit()}
        confirmLoading={loading}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={updateProgress}
        >
          <Form.Item
            name="completion_percentage"
            label="Процент завершения"
            rules={[{ required: true, message: 'Укажите процент завершения' }]}
          >
            <InputNumber
              min={0}
              max={100}
              step={0.1}
              style={{ width: '100%' }}
              formatter={value => `${value}%`}
              parser={value => value!.replace('%', '')}
            />
          </Form.Item>
          
          <Form.Item
            name="status"
            label="Статус"
            rules={[{ required: true, message: 'Выберите статус' }]}
          >
            <Select>
              <Select.Option value="pending">Ожидание</Select.Option>
              <Select.Option value="in_progress">В процессе</Select.Option>
              <Select.Option value="completed">Завершено</Select.Option>
              <Select.Option value="paused">Приостановлено</Select.Option>
            </Select>
          </Form.Item>
          
          <Form.Item
            name="notes"
            label="Заметки"
          >
            <TextArea rows={3} placeholder="Дополнительная информация о прогрессе..." />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default ActivityGoalsIntegration;
